<?php
namespace App\Controllers;

use App\Core\Database;
use App\Helpers\AuthHelper;
use App\Helpers\NotificationHelper;
use App\Services\StockService;
use PDO;

class LoanWorkflowController extends LoanController {
    private function go(string $p): void { header('Location: '.url($p)); exit; }
    private function audit(PDO $pdo,int $uid,string $action,int $id,string $note,?array $old=null,?array $new=null):void{
        $stmt=$pdo->prepare("INSERT INTO audit_logs (user_id,action,entity,entity_id,old_data,new_data,ip_address,user_agent) VALUES (?,?,'loans',?,?,?,?,?)");
        $stmt->execute([$uid,$action,$id,$old?json_encode($old):null,$new?json_encode(array_merge($new??[],['notes'=>$note])):json_encode(['notes'=>$note]),$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??null]);
    }
    public function index(){
        $pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$search=trim($_GET['search']??'');$status=trim($_GET['status']??'');$page=max(1,(int)($_GET['page']??1));$limit=15;$offset=($page-1)*$limit;
        $w=['1=1'];$p=[];if(!AuthHelper::hasRole(['SUPERADMIN','ADMIN'])){$w[]='l.borrower_id=?';$p[]=$u['id'];}if($search!==''){$w[]='(u.name LIKE ? OR wh.name LIKE ?)';$p[]="%$search%";$p[]="%$search%";}if($status!==''){$w[]='l.status=?';$p[]=$status;}
        $where='WHERE '.implode(' AND ',$w);$c=$pdo->prepare("SELECT COUNT(*) FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses wh ON wh.id=l.warehouse_id $where");$c->execute($p);$totalItems=(int)$c->fetchColumn();$totalPages=max(1,(int)ceil($totalItems/$limit));
        $s=$pdo->prepare("SELECT l.*,u.name borrower_name,wh.name warehouse_name FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses wh ON wh.id=l.warehouse_id $where ORDER BY l.id DESC LIMIT $limit OFFSET $offset");$s->execute($p);$loans=$s->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/index.php';
    }
    public function create(){
        AuthHelper::requireRole(['TEKNISI_NOC']);$pdo=Database::getInstance()->getConnection();$warehouses=$pdo->query("SELECT id,name FROM warehouses WHERE is_active=1 ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);$items=$pdo->query("SELECT id,nama,is_serialized FROM master_items WHERE is_active=1 ORDER BY nama")->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT id FROM submissions WHERE status IN ('APPROVED','PARTIAL_APPROVED') AND submitted_by=? ORDER BY id DESC");$s->execute([AuthHelper::user()['id']]);$submissions=$s->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/create.php';
    }
    public function store(){
        AuthHelper::requireRole(['TEKNISI_NOC']);if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/loans/create');}
        $pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$wh=(int)($_POST['warehouse_id']??0);$type=$_POST['loan_type']??'INTERNAL';$sid=!empty($_POST['submission_id'])?(int)$_POST['submission_id']:null;$due=$_POST['due_date']??null;$notes=trim($_POST['notes']??'');if($wh<=0){$_SESSION['error']='Gudang asal wajib dipilih.';$this->go('/loans/create');}
        $sources=$_POST['source_types']??[];$itemIds=$_POST['item_ids']??[];$qtys=$_POST['quantities']??[];$sns=$_POST['sn_list']??[];$manual=$_POST['manual_names']??[];if(!$sources){$_SESSION['error']='Tambahkan minimal satu barang.';$this->go('/loans/create');}
        if($sid){$q=$pdo->prepare("SELECT id FROM submissions WHERE id=? AND submitted_by=? AND status IN ('APPROVED','PARTIAL_APPROVED')");$q->execute([$sid,$uid]);if(!$q->fetchColumn()){$_SESSION['error']='Pengajuan terkait tidak valid.';$this->go('/loans/create');}}
        $svc=new StockService();$code=\App\Helpers\TransactionHelper::generateCode('LOAN','loans');
        try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO loans(transaction_code,borrower_id,warehouse_id,submission_id,loan_type,loan_date,due_date,status,notes,processed_by) VALUES(?,?,?,?,?,NOW(),?,'PENDING_APPROVAL',?,?)");$q->execute([$code,$uid,$wh,$sid,$type,$due,$notes,$uid]);$loanId=(int)$pdo->lastInsertId();$stockIns=$pdo->prepare("INSERT INTO loan_items(loan_id,master_item_id,quantity,returned_quantity) VALUES(?,?,?,0)");$manualIns=$pdo->prepare("INSERT INTO loan_manual_items(loan_id,name,specification,unit,quantity,returned_quantity) VALUES(?,?,NULL,NULL,?,0)");$snIns=$pdo->prepare("INSERT INTO loan_item_serials(loan_item_id,serial_number_id,status) VALUES(?,?,'PENDING')");$snQ=$pdo->prepare("SELECT id,master_item_id,status FROM serial_numbers WHERE serial_number=? AND current_warehouse_id=? FOR UPDATE");$lines=0;
            foreach($sources as $i=>$source){$qty=(int)($qtys[$i]??0);if($qty<1)continue;if($source==='MANUAL'){$name=trim($manual[$i]??'');if($name==='')throw new \Exception('Nama barang manual wajib diisi.');$manualIns->execute([$loanId,$name,$qty]);$lines++;continue;}$itemId=(int)($itemIds[$i]??0);$m=$pdo->prepare("SELECT id,nama,is_serialized FROM master_items WHERE id=? AND is_active=1");$m->execute([$itemId]);$item=$m->fetch(PDO::FETCH_ASSOC);if(!$item)throw new \Exception('Barang dari stok tidak valid.');$st=$pdo->prepare("SELECT quantity FROM stocks WHERE master_item_id=? AND warehouse_id=? FOR UPDATE");$st->execute([$itemId,$wh]);if((int)$st->fetchColumn()<$qty)throw new \Exception("Stok {$item['nama']} tidak mencukupi.");$stockIns->execute([$loanId,$itemId,$qty]);$lineId=(int)$pdo->lastInsertId();$lines++;if((int)$item['is_serialized']===1){$selected=[];foreach((array)($sns[$i]??[]) as $sn){$sn=trim((string)$sn);if($sn!=='')$selected[]=$sn;}if(count($selected)!==$qty)throw new \Exception("Pilih $qty serial number untuk {$item['nama']}.");foreach($selected as $sn){$snQ->execute([$sn,$wh]);$sr=$snQ->fetch(PDO::FETCH_ASSOC);if(!$sr||$sr['master_item_id']!=$itemId||$sr['status']!=='AVAILABLE')throw new \Exception("Serial Number $sn tidak tersedia.");$svc->moveSerial($sr['id'],'RESERVED',$wh,null,null,'loan_request',$loanId,'Reservasi serial peminjaman.');$snIns->execute([$lineId,$sr['id']]);}}}
            if($lines===0)throw new \Exception('Tidak ada barang valid.');$this->audit($pdo,$uid,'CREATE',$loanId,'Peminjaman diajukan dan menunggu persetujuan Admin.',null,['status'=>'PENDING_APPROVAL']);$pdo->commit();NotificationHelper::createForRoleOnce('ADMIN','Peminjaman Baru Menunggu Persetujuan',AuthHelper::user()['name'].' mengajukan peminjaman baru.','info','/loans/show?id='.$loanId);$_SESSION['success']='Peminjaman berhasil diajukan dan menunggu persetujuan Admin.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal mengajukan peminjaman: '.$e->getMessage();}$this->go('/loans');
    }
    public function approve(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/loans');}$id=(int)($_POST['id']??0);$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='PENDING_APPROVAL')throw new \Exception('Peminjaman sudah diproses.');$it=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=?");$it->execute([$id]);foreach($it->fetchAll(PDO::FETCH_ASSOC) as $i){$st=$pdo->prepare("SELECT quantity FROM stocks WHERE master_item_id=? AND warehouse_id=? FOR UPDATE");$st->execute([$i['master_item_id'],$loan['warehouse_id']]);if((int)$st->fetchColumn()<(int)$i['quantity'])throw new \Exception("Stok {$i['nama']} tidak mencukupi.");if((int)$i['is_serialized']===1){$sn=$pdo->prepare("SELECT sn.status FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id WHERE lis.loan_item_id=?");$sn->execute([$i['id']]);$rows=$sn->fetchAll(PDO::FETCH_COLUMN);if(count($rows)!==(int)$i['quantity'])throw new \Exception("Serial {$i['nama']} belum lengkap.");foreach($rows as $stt)if(!in_array($stt,['RESERVED','AVAILABLE'],true))throw new \Exception("Serial {$i['nama']} sudah tidak tersedia.");}}$note=trim($_POST['approval_notes']??'');$pdo->prepare("UPDATE loans SET status='APPROVED',approved_by=?,approved_at=NOW(),approval_notes=?,processed_by=? WHERE id=?")->execute([$uid,$note!==''?$note:null,$uid,$id]);$this->audit($pdo,$uid,'APPROVE',$id,$note!==''?$note:'Peminjaman disetujui.',['status'=>'PENDING_APPROVAL'],['status'=>'APPROVED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Peminjaman Disetujui','Peminjaman Anda disetujui dan menunggu serah terima barang.','success','/loans/show?id='.$id);$_SESSION['success']='Peminjaman disetujui.';}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal menyetujui: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function reject(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/loans');}$id=(int)($_POST['id']??0);$reason=trim($_POST['approval_notes']??'');if($reason===''){$_SESSION['error']='Alasan penolakan wajib diisi.';$this->go('/loans/show?id='.$id);} $pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT borrower_id,warehouse_id,status FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='PENDING_APPROVAL')throw new \Exception('Peminjaman sudah diproses.');$ss=$pdo->prepare("SELECT sn.id FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id JOIN loan_items li ON li.id=lis.loan_item_id WHERE li.loan_id=? AND lis.status='PENDING'");$ss->execute([$id]);$svc=new StockService();foreach($ss->fetchAll(PDO::FETCH_COLUMN) as $snId)$svc->moveSerial($snId,'AVAILABLE',$loan['warehouse_id'],null,null,'loan_reject',$id,'Reservasi dibatalkan.');$pdo->prepare("DELETE lis FROM loan_item_serials lis JOIN loan_items li ON li.id=lis.loan_item_id WHERE li.loan_id=? AND lis.status='PENDING'")->execute([$id]);$pdo->prepare("UPDATE loans SET status='REJECTED',approved_by=?,approved_at=NOW(),approval_notes=?,processed_by=? WHERE id=?")->execute([$uid,$reason,$uid,$id]);$this->audit($pdo,$uid,'REJECT',$id,$reason,['status'=>'PENDING_APPROVAL'],['status'=>'REJECTED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Peminjaman Ditolak','Pengajuan peminjaman Anda ditolak. Alasan tersedia di detail.','danger','/loans/show?id='.$id);$_SESSION['success']='Peminjaman ditolak.';}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal menolak: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function handover(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/loans');}$id=(int)($_POST['id']??0);$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$svc=new StockService();
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? FOR UPDATE");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||$loan['status']!=='APPROVED')throw new \Exception('Peminjaman belum siap diserahkan.');$it=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=?");$it->execute([$id]);foreach($it->fetchAll(PDO::FETCH_ASSOC) as $i){$qty=(int)$i['quantity'];$st=$pdo->prepare("SELECT quantity FROM stocks WHERE master_item_id=? AND warehouse_id=? FOR UPDATE");$st->execute([$i['master_item_id'],$loan['warehouse_id']]);if((int)$st->fetchColumn()<$qty)throw new \Exception("Stok {$i['nama']} berubah dan tidak mencukupi.");if((int)$i['is_serialized']===1){$sn=$pdo->prepare("SELECT sn.id,sn.status FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id WHERE lis.loan_item_id=? AND lis.status='PENDING' FOR UPDATE");$sn->execute([$i['id']]);$rows=$sn->fetchAll(PDO::FETCH_ASSOC);if(count($rows)!==$qty)throw new \Exception("Serial {$i['nama']} belum lengkap.");foreach($rows as $r){if(!in_array($r['status'],['RESERVED','AVAILABLE'],true))throw new \Exception("Serial {$i['nama']} tidak tersedia.");$svc->moveSerial($r['id'],'LOANED',null,null,(int)$loan['borrower_id'],'loan',$id,'Serah terima peminjaman.');$pdo->prepare("UPDATE loan_item_serials SET status='BORROWED' WHERE loan_item_id=? AND serial_number_id=?")->execute([$i['id'],$r['id']]);}}$svc->mutateStock($i['master_item_id'],$loan['warehouse_id'],-$qty,'LOAN_OUT','loans',$id,'Serah terima peminjaman.');}$pdo->prepare("UPDATE loans SET status='BORROWED',handed_over_by=?,handed_over_at=NOW(),processed_by=? WHERE id=?")->execute([$uid,$uid,$id]);$this->audit($pdo,$uid,'HANDOVER',$id,'Barang diserahkan kepada teknisi.',['status'=>'APPROVED'],['status'=>'BORROWED']);$pdo->commit();NotificationHelper::createForUsers([(int)$loan['borrower_id']],'Barang Peminjaman Diserahkan','Barang sudah diserahkan dan sekarang berada dalam penguasaan Anda.','success','/loans/show?id='.$id);$_SESSION['success']='Serah terima berhasil. Stok dan custody sudah diperbarui.';}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal serah terima: '.$e->getMessage();}$this->go('/loans/show?id='.$id);
    }
    public function show(){
        $id=(int)($_GET['id']??0);$pdo=Database::getInstance()->getConnection();$user=AuthHelper::user();$q=$pdo->prepare("SELECT l.*,u.name borrower_name,w.name warehouse_name FROM loans l JOIN users u ON u.id=l.borrower_id JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=?");$q->execute([$id]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan){$_SESSION['error']='Peminjaman tidak ditemukan.';$this->go('/loans');}if($user['role']==='TEKNISI_NOC'&&(int)$loan['borrower_id']!==(int)$user['id']){$_SESSION['error']='Anda tidak memiliki akses.';$this->go('/loans');}
        $items=[];$s=$pdo->prepare("SELECT li.id,li.quantity,li.returned_quantity,m.nama,m.is_serialized,'STOCK' source_type FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? ORDER BY li.id");$s->execute([$id]);foreach($s->fetchAll(PDO::FETCH_ASSOC) as $r)$items[]=$r;$m=$pdo->prepare("SELECT id,name nama,quantity,returned_quantity,specification,unit,'MANUAL' source_type FROM loan_manual_items WHERE loan_id=? ORDER BY id");$m->execute([$id]);foreach($m->fetchAll(PDO::FETCH_ASSOC) as $r){$r['is_serialized']=0;$r['serial_numbers']=[];$items[]=$r;}$sn=$pdo->prepare("SELECT sn.serial_number,lis.status FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id WHERE lis.loan_item_id=? ORDER BY sn.serial_number");foreach($items as &$i){if($i['source_type']==='STOCK'&&(int)$i['is_serialized']===1){$sn->execute([(int)$i['id']]);$i['serial_numbers']=$sn->fetchAll(PDO::FETCH_ASSOC);}else$i['serial_numbers']=[];}unset($i);$a=$pdo->prepare("SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity='loans' AND a.entity_id=? ORDER BY a.created_at DESC,a.id DESC");$a->execute([$id]);$timeline=$a->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/loans/show.php';
    }
}
